"""Exam 2: all source subparts, with independently derived solutions."""
def create(L,S,P,R,Q,E):
    f='e2-f25'; s='e2-s26'
    gauss=[R(10,28,'用对称性选择高斯面','Choosing a Gaussian surface'),R(11,22,'介质与极化','Dielectrics and polarization')]
    sphere=Q(f,1,'球对称电荷与高斯定律','Spherical symmetry & Gauss’s law',('高斯定律','Gauss’s law'),
      (r'半径 $a$ 的实心球具有均匀体电荷密度 $\rho_0$，外侧 $r=b$ 的导体薄壳带有等量异号的总电荷。各区初始介电常数为 $\epsilon_0$。对每一区域画出高斯面并求电场。',
       r'A solid sphere of radius $a$ carries uniform volume charge density $\rho_0$. A thin conducting shell at $r=b$ carries equal and opposite total charge. Initially the permittivity is $\epsilon_0$. Draw a Gaussian surface and determine the field in each region.'),
      [r'Q_a=\frac43\pi a^3\rho_0',r'Q_b=-Q_a',r'0<a<b'],12,2,[.12,.255,.75,.215],gauss,[
        P('a',1,'画出 $0<r<a$ 的高斯面。','Draw the Gaussian surface for $0<r<a$.',[
          S('先写公式表中的高斯定律：闭合面的电位移通量等于面内自由电荷。', 'Begin with the crib equation: displacement flux through a closed surface equals its enclosed free charge.', '\\oiint_S\\mathbf D\\cdot d\\mathbf S=\\iiint_{\\mathcal V}\\rho\\,d\\mathcal V=Q_{\\mathrm{enc}}', ['gauss']),
          S('球对称使电场沿径向；同一半径上的场强相同。这里用 R 表示固定的高斯面半径，避免和积分变量混淆。', 'Spherical symmetry makes the field radial and constant at a fixed radius. Use R for the fixed Gaussian radius, distinct from integration coordinates.', '\\mathbf E(R)=E_r(R)\\hat{\\mathbf r},\\qquad \\mathbf D(R)=\\epsilon_0 E_r(R)\\hat{\\mathbf r}', ['constitutive']),
          S('先画半径 a 的带电实心球和半径 b 的导体薄壳，再在实心球内画与二者同心的虚线球面。', 'Draw the charged solid sphere of radius a and the conducting shell of radius b, then a concentric dashed Gaussian sphere inside the solid sphere.', '0<R<a<b,\\qquad S_R:\\ |\\mathbf x|=R', []),
          S('在同一个球心上标出 a、b、R 三根半径箭头；R 箭头必须止于虚线面，法向从该面向外。', 'Start all three radius arrows a, b and R at the same center. End R on the dashed surface and draw its outward normal from that surface.', 'd\\mathbf S=\\hat{\\mathbf r}\\,R^2\\sin\\theta\\,d\\theta\\,d\\phi,\\quad 0\\le\\theta\\le\\pi,\\quad 0\\le\\phi<2\\pi', ['geometry']),
          S('该闭合面只包围半径 R 内的体电荷；a 与 b 是材料边界，不是此问选取的高斯面。', 'The closed surface encloses only the volume charge within R. The radii a and b are material boundaries, not the chosen Gaussian surface.', 'S_R:\\ |\\mathbf x|=R,\\quad 0<R<a', [])],'S_R:\\ |\\mathbf x|=R,\\quad 0<R<a',2,figure='sphere-inner',spatialFigure='e2-f25-q1',figureCaption=L('同心球截面，虚线表示半径 0<R<a 的闭合高斯球面；半径 a、b、R 共享球心。', 'Concentric-sphere section with the closed Gaussian sphere at 0<R<a; radii a, b and R share one center.'),note=L('原解的高斯面草图在内球附近标了 ρsa，但题干给定的是均匀体电荷密度 ρ₀。本图按题干使用 ρ₀；虚线圆是三维闭合高斯球面的截面，R 为其半径。a、b、R 都从同一球心量起。', 'The official Gaussian-surface sketches label the inner sphere with ρsa, but the prompt specifies uniform volume density ρ₀. These diagrams use ρ₀ from the prompt. The dashed circle is a section of a closed spherical Gaussian surface of radius R; a, b and R share one center.')),
        P('b',3,'求 $0<r<a$ 内的电场。','Find the field for $0<r<a$.',[
          S('从原始高斯定律开始，并用本构关系把 D 换成电场。', 'Start from Gauss’s law and substitute the constitutive relation for D.', '\\oiint_{S_R}\\mathbf D\\cdot d\\mathbf S=Q_{\\mathrm{enc}},\\qquad \\mathbf D=\\epsilon_0\\mathbf E', ['gauss', 'constitutive']),
          S('在半径固定为 R 的球面上代入径向场和球坐标面积元，先保留点积。', 'On the sphere of fixed radius R, substitute the radial field and spherical area element, retaining the dot product.', '\\Phi_D=\\int_0^{2\\pi}\\!\\int_0^\\pi [\\epsilon_0E_r(R)\\hat{\\mathbf r}]\\cdot[\\hat{\\mathbf r}R^2\\sin\\theta]\\,d\\theta\\,d\\phi', ['geometry']),
          S('两个单位法向的点积为 1；场强不随角度变化，可移到积分号外。', 'The unit normals have dot product one. The field is angle independent, so take it outside the integrals.', '\\Phi_D=\\epsilon_0E_r(R)R^2\\left(\\int_0^{2\\pi}d\\phi\\right)\\left(\\int_0^\\pi\\sin\\theta\\,d\\theta\\right)', []),
          S('分别求两个角积分，不能直接省略球面积的来源。', 'Evaluate both angular integrals explicitly to obtain the spherical area factor.', '\\int_0^{2\\pi}d\\phi=2\\pi,\\quad [-\\cos\\theta]_0^\\pi=2,\\quad \\Phi_D=4\\pi\\epsilon_0R^2E_r(R)', []),
          S('另算包围电荷：密度为常数，径向积分从 0 到高斯半径 R。用 r′ 作为体积分变量。', 'Compute enclosed charge separately. Density is constant and the radial limit is R; use r′ as the volume integration variable.', 'Q_{\\mathrm{enc}}=\\int_0^{2\\pi}\\!\\int_0^\\pi\\!\\int_0^R \\rho_0(r^\\prime)^2\\sin\\theta\\,dr^\\prime d\\theta d\\phi', ['geometry']),
          S('将三个积分相乘，逐项求值。外面的薄壳没有被这个高斯面包围。', 'Evaluate the three factors. The outer conducting shell is not enclosed by this surface.', 'Q_{\\mathrm{enc}}=\\rho_0(2\\pi)(2)\\left[\\frac{(r^\\prime)^3}{3}\\right]_0^R=\\frac{4\\pi\\rho_0R^3}{3}', []),
          S('令通量等于包围电荷，两边除以 4πε₀R²；R³/R² 留下 R。', 'Equate flux and enclosed charge, then divide by 4πε₀R²; R³/R² leaves R.', '4\\pi\\epsilon_0R^2E_r(R)=\\frac{4\\pi\\rho_0R^3}{3}\\quad\\Longrightarrow\\quad E_r(R)=\\frac{\\rho_0R^3}{3\\epsilon_0R^2}', []),
          S('最后把任意高斯半径 R 改记为观察半径 r，并补回径向单位矢量。', 'Relabel the arbitrary Gaussian radius R as the observation radius r and restore the radial unit vector.', '\\mathbf E(r)=\\frac{\\rho_0 r}{3\\epsilon_0}\\hat{\\mathbf r}', [])],r'\mathbf E(r)=\frac{\rho_0 r}{3\epsilon_0}\hat{\mathbf r}',2),
        P('c',1,'画出 $a<r<b$ 的高斯面。','Draw the Gaussian surface for $a<r<b$.',[
          S('仍从闭合面高斯定律出发，球对称要求使用同心球面。', 'Again use Gauss’s law on a closed surface; spherical symmetry suggests a concentric sphere.', '\\oiint_{S_R}\\mathbf D\\cdot d\\mathbf S=Q_{\\mathrm{enc}}', ['gauss']),
          S('将虚线高斯面画在半径 a 的实心球之外、半径 b 的导体薄壳之内。', 'Place the dashed Gaussian sphere outside the solid sphere of radius a and inside the shell of radius b.', 'a<R<b,\\qquad S_R:\\ |\\mathbf x|=R', []),
          S('a、b、R 都从同一个球心量起。高斯面包围整个带电实心球，但不包围外壳电荷。', 'Measure a, b and R from the same center. The Gaussian sphere encloses the whole charged solid sphere but excludes the shell charge.', 'Q_{\\mathrm{enc}}=\\iiint_{r^\\prime<a}\\rho_0\\,d\\mathcal V,\\qquad Q_b\\ \\text{excluded}', ['geometry']),
          S('在高斯面上标出向外法向。原题含等号时，b 处的场须取介质一侧 b⁻ 的极限。', 'Mark the outward surface normal. At the printed endpoint b, the dielectric-region field means the one-sided limit b⁻.', 'd\\mathbf S=\\hat{\\mathbf r}R^2\\sin\\theta\\,d\\theta\\,d\\phi', []),
          S('图中虚线球面的半径满足下式，后续积分在这一个固定半径上进行。', 'The dashed spherical surface has the following radius range; the subsequent flux integral uses this fixed radius.', 'S_R:\\ |\\mathbf x|=R,\\quad a<R<b', [])],'S_R:\\ |\\mathbf x|=R,\\quad a<R<b',2,3,figure='sphere-middle',figureCaption=L('同心球截面，高斯球面位于 a<R<b，只包围内球体电荷；虚线为高斯面截线。', 'Concentric-sphere section with a<R<b; the dashed Gaussian surface encloses only the solid-sphere volume charge.')),
        P('d',3,'求 $a<r<b$ 的电场。','Find the field for $a<r<b$.',[
          S('先写高斯定律及 D 与 E 的关系，取 a<R<b 的同心球面。', 'Write Gauss’s law and the D–E relation on a concentric sphere with a<R<b.', '\\oiint_{S_R}\\mathbf D\\cdot d\\mathbf S=Q_{\\mathrm{enc}},\\qquad\\mathbf D=\\epsilon_0\\mathbf E', ['gauss', 'constitutive']),
          S('代入球面面积元并计算点积；同心球面上的场强为常数。', 'Substitute the spherical area element and evaluate the dot product; field magnitude is constant over the sphere.', '\\Phi_D=\\epsilon_0 E_r(R)R^2\\int_0^{2\\pi}\\!\\int_0^\\pi\\sin\\theta\\,d\\theta d\\phi', ['geometry']),
          S('展开角积分，得到通量系数。', 'Evaluate the angular factors to obtain the flux coefficient.', '\\Phi_D=\\epsilon_0E_r(R)R^2(2\\pi)(2)=4\\pi\\epsilon_0R^2E_r(R)', []),
          S('体电荷只存在于 0≤r′≤a。即使高斯半径为 R，电荷积分上限仍是 a。', 'Volume charge exists only for 0≤r′≤a. The charge integral ends at a even though the Gaussian radius is R.', 'Q_{\\mathrm{enc}}=\\int_0^{2\\pi}\\!\\int_0^\\pi\\!\\int_0^a \\rho_0(r^\\prime)^2\\sin\\theta\\,dr^\\prime d\\theta d\\phi', []),
          S('径向积分为 a³/3，角积分乘出 4π；a 到 R 的无电荷区不增加包围电荷。', 'The radial integral gives a³/3 and the angular integrals give 4π. The charge-free region from a to R adds no enclosed charge.', 'Q_{\\mathrm{enc}}=\\rho_0(2\\pi)(2)\\left[\\frac{(r^\\prime)^3}{3}\\right]_0^a=\\frac{4\\pi\\rho_0a^3}{3}', []),
          S('把右侧电荷代入高斯定律，并除以通量系数求出径向场。', 'Substitute the enclosed charge into Gauss’s law and divide by the flux coefficient.', 'E_r(R)=\\frac{Q_{\\mathrm{enc}}}{4\\pi\\epsilon_0R^2}=\\frac{4\\pi\\rho_0a^3/3}{4\\pi\\epsilon_0R^2}', []),
          S('改用观察坐标 r 表示结果。r=a 时与内区结果连续；r=b 表示 b⁻。', 'Express the result using observation radius r. It is continuous with the inner result at a; the endpoint b means b⁻.', '\\mathbf E(r)=\\frac{\\rho_0 a^3}{3\\epsilon_0 r^2}\\hat{\\mathbf r}', [])],r'\mathbf E(r)=\frac{\rho_0 a^3}{3\epsilon_0 r^2}\hat{\mathbf r}',3),
        P('e',1,'画出 $r>b$ 的高斯面。','Draw the Gaussian surface for $r>b$.',[
          S('先写闭合面的高斯定律；所选面现在必须包住实心球和导体薄壳。', 'Begin with Gauss’s law; the chosen closed surface must now enclose both the solid sphere and conducting shell.', '\\oiint_{S_R}\\mathbf D\\cdot d\\mathbf S=Q_{\\mathrm{enc}}', ['gauss']),
          S('以同一球心画半径 R>b 的虚线球面，并从球心画出 R 箭头至虚线面。', 'Draw a concentric dashed sphere with R>b and a radius arrow from the common center to that dashed surface.', '0<a<b<R', []),
          S('分别标明 a 内的体电荷和 b 上的表面电荷；外面的虚线才是高斯面。', 'Distinguish the volume charge within a, the surface charge at b and the outer dashed Gaussian surface.', 'Q_{\\mathrm{enc}}=Q_a+Q_b,\\qquad Q_b=-Q_a', []),
          S('面法向仍向外。零场结论来自下一问的电荷相消，而不是改变高斯面形状。', 'The surface normal remains outward. The zero field follows from charge cancellation in the next part, not from changing the surface geometry.', 'S_R:\\ |\\mathbf x|=R,\\quad R>b', [])],'S_R:\\ |\\mathbf x|=R,\\quad R>b',3,figure='sphere-outer',figureCaption=L('同心球截面，高斯球面位于 R>b，同时包围等量异号的内球与外壳电荷。', 'Concentric-sphere section with R>b; the Gaussian surface encloses the equal and opposite sphere and shell charges.')),
        P('f',1,'求 $r>b$ 的电场。','Find the field for $r>b$.',[
          S('在壳外同心球面应用高斯定律，并代入真空本构关系。', 'Apply Gauss’s law outside the shell and substitute the vacuum constitutive relation.', '\\oiint_{S_R}\\mathbf D\\cdot d\\mathbf S=Q_{\\mathrm{enc}},\\qquad\\mathbf D=\\epsilon_0\\mathbf E', ['gauss', 'constitutive']),
          S('球对称使通量积分化为球面积乘径向电位移。', 'Spherical symmetry reduces the flux to spherical area times radial displacement.', '\\Phi_D=\\epsilon_0E_r(R)R^2(2\\pi)(2)=4\\pi\\epsilon_0R^2E_r(R)', []),
          S('将内球体电荷与外壳等量异号的电荷分别写出，再相加。', 'Write the solid-sphere charge and the equal, opposite shell charge separately before adding them.', 'Q_a=\\frac{4\\pi a^3\\rho_0}{3},\\quad Q_b=-\\frac{4\\pi a^3\\rho_0}{3},\\quad Q_{\\mathrm{enc}}=0', []),
          S('代入定律并除以非零的 4πε₀R²。由球对称性，零总通量在这里推出场本身为零。', 'Substitute and divide by nonzero 4πε₀R². With spherical symmetry, zero flux here implies zero field itself.', '4\\pi\\epsilon_0R^2E_r(R)=0\\quad\\Longrightarrow\\quad E_r(R)=0', []),
          S('恢复矢量形式并注明适用区域。', 'Restore vector notation and state the domain.', '\\mathbf E(r)=\\mathbf 0\\quad(r>b)', [])],r'\mathbf E(r)=\mathbf 0\quad(r>b)',3),
        P('g',2,r'若把 $a<r<b$ 换为 $\epsilon>\epsilon_0$ 的介质，电势差如何变化？用极化解释。',r'How does replacing $a<r<b$ with a dielectric of $\epsilon>\epsilon_0$ change the potential difference? Explain using polarization.',[
          S('比较电势差前，先写原表的电势积分及本构关系。', 'Before comparing potentials, write the crib potential integral and constitutive relation.', 'V(b)-V(a)=-\\int_a^b\\mathbf E\\cdot d\\mathbf l,\\qquad\\mathbf D=\\epsilon\\mathbf E', ['potential', 'constitutive']),
          S('更换介质时保持题设自由电荷不变，因此同一高斯面上的 D 仍由同一个包围电荷确定。', 'Replacing the dielectric leaves the specified free charges fixed, so D on a given Gaussian surface is set by the same enclosed charge.', 'D_r(r)=\\frac{Q_a}{4\\pi r^2}=\\frac{\\rho_0a^3}{3r^2}', ['gauss']),
          S('分别除以新旧介电常数得到两个电场；不能把 D 和 E 同时按相同比例缩小。', 'Divide by the new and old permittivities to obtain the fields; D does not decrease along with E.', 'E_\\epsilon(r)=\\frac{\\rho_0a^3}{3\\epsilon r^2}=\\frac{\\epsilon_0}{\\epsilon}E_{\\mathrm{vac}}(r)', []),
          S('沿径向从 a 到 b 积分。若用 V(a)−V(b)，电势积分外侧负号相应反转。', 'Integrate radially from a to b. For V(a)−V(b), reverse the leading sign accordingly.', 'V(a)-V(b)=\\frac{\\rho_0a^3}{3\\epsilon}\\int_a^b r^{-2}\\,dr', []),
          S('写出原函数并代入上下限。', 'Write the antiderivative and evaluate both limits.', 'V(a)-V(b)=\\frac{\\rho_0a^3}{3\\epsilon}\\left[-\\frac1r\\right]_a^b=\\frac{\\rho_0a^3}{3\\epsilon}\\left(\\frac1a-\\frac1b\\right)', []),
          S('诱导偶极的极化响应减小同一自由电荷产生的电场。取绝对值比较，结论不依赖 ρ₀ 的符号。', 'The induced-dipole polarization response reduces the field for the same free charge. Compare magnitudes so the conclusion is independent of the sign of ρ₀.', '|\\Delta V_\\epsilon|=\\frac{\\epsilon_0}{\\epsilon}|\\Delta V_{\\mathrm{vac}}|<|\\Delta V_{\\mathrm{vac}}|', [])],r'|\Delta V_{\epsilon}|=\frac{\epsilon_0}{\epsilon}|\Delta V_{\mathrm{vac}}|<|\Delta V_{\mathrm{vac}}|',3)
      ],caption=('虚线为可选高斯球面；右侧为归一化电场剖面，示意取 b=2a。','Dashed curves are Gaussian spheres. The normalized field profile uses the illustrative ratio b=2a.'),note=L('场在导体薄壳处有跳变：a≤r≤b 的公式应理解为介质内极限，不能把介质中的场值当成导体内的场。','The field jumps at the conducting shell. Interpret the a≤r≤b expression as a dielectric-side limit, not the field inside the conductor.'))

    plates=Q(f,2,'双介质平板电容器','A capacitor with two dielectrics',('边界条件 · 电场能量','Boundary conditions · energy'),
      (r'两导体板位于 $x=0,L$，电位分别为 $V_0,V_1$。板高 $H$、深 $W$；上半区域介电常数 $\epsilon_1$，下半区域 $\epsilon_2$。忽略边缘效应。',
       r'Conducting plates at $x=0,L$ are held at $V_0,V_1$. Their height is $H$ and depth is $W$. The upper half has permittivity $\epsilon_1$ and the lower half $\epsilon_2$. Neglect fringing.'),
      [r'A_1=A_2=HW/2',r'\Delta V=V_1-V_0',r'\rho_s^{\mathrm{interface}}=0'],8,4,[.16,.28,.64,.20],
      [R(12,14,'电场切向连续','Tangential-field continuity'),R(12,29,'能量法求电容','Capacitance from energy')],[
        P('a',2,r'求介质 2 的 $\mathbf E_2$ 与 $\mathbf D_2$。',r'Find $\mathbf E_2$ and $\mathbf D_2$.',[
          S('先写切向电场连续条件及本构关系。介质分界面法向为 z，题中的电场沿 x，属于切向分量。', 'Write tangential-field continuity and the constitutive relation. The dielectric interface normal is z, so the x-directed field is tangential.', 'E_{1t}=E_{2t},\\qquad\\mathbf D_2=\\epsilon_2\\mathbf E_2', ['boundary', 'constitutive']),
          S('用给定的两块等势板求电位函数：无边缘效应时电位随 x 线性变化。', 'Find the potential from the stated plate potentials: without fringing it varies linearly with x.', 'V(x)=V_0+\\frac{V_1-V_0}{L}x,\\quad V(0)=V_0,\\quad V(L)=V_1', []),
          S('按 E=−∇V 求导。题面与官方答案给出的正号和板电位矛盾，下面使用与板电位一致的方向。', 'Differentiate using E=−∇V. The printed positive sign conflicts with the plate potentials; use the direction consistent with those potentials.', '\\mathbf E_1=-\\frac{dV}{dx}\\hat{\\mathbf x}=-\\frac{V_1-V_0}{L}\\hat{\\mathbf x}', ['gradient']),
          S('切向连续给出 E₂=E₁；再将它代入 D₂=ε₂E₂，法向分量均为零。', 'Tangential continuity gives E₂=E₁. Substitute this into D₂=ε₂E₂; both normal components are zero.', 'E_{2x}=E_{1x}=\\frac{V_0-V_1}{L},\\qquad D_{2x}=\\epsilon_2\\frac{V_0-V_1}{L}', []),
          S('组合为所求两个矢量。若沿用试卷印出的场方向，E 和 D 的符号一起反转，后面的能量不变。', 'Assemble the requested vectors. Following the printed field instead reverses both E and D; the later energy is unchanged.', '\\mathbf E_2=\\frac{V_0-V_1}{L}\\hat{\\mathbf x},\\quad\\mathbf D_2=\\epsilon_2\\frac{V_0-V_1}{L}\\hat{\\mathbf x}', [])],r'\mathbf E_2=\frac{V_0-V_1}{L}\hat{\mathbf x},\quad\mathbf D_2=\epsilon_2\frac{V_0-V_1}{L}\hat{\mathbf x}',4,5,
          note=L('原题与官方解把 E 写成 +(V₁−V₀)/L，与所给边界电位及 E=−∇V 不一致。这里采用物理一致的负号；若按题面给定场作答，D 同时反号，后续能量和电容不受影响。','The prompt and official solution print +(V₁−V₀)/L, inconsistent with the stated potentials and E=−∇V. This version uses the consistent minus sign. Taking the printed field instead also reverses D; energy and capacitance remain unchanged.')),
        P('b',4,'用体积分求总电场能量。','Find total stored energy by volume integration.',[
          S('先写电场能量的体积分原式；两种介质须分别积分后相加。', 'Begin with the field-energy volume integral; integrate each dielectric separately and then add.', 'W_e=\\frac12\\iiint_{\\mathcal V}\\epsilon|\\mathbf E|^2\\,d\\mathcal V=W_{e1}+W_{e2}', ['energy']),
          S('两区域的场强大小相同，平方后电场方向或题面符号差异不会影响能量。', 'The field magnitudes agree in both regions. Squaring removes dependence on field direction or the printed sign.', '|\\mathbf E_1|^2=|\\mathbf E_2|^2=\\frac{(V_1-V_0)^2}{L^2}', []),
          S('区域 1 的三个积分范围分别为 x 从 0 到 L、y 从 0 到 W、z 从 H/2 到 H。', 'For region 1, integrate x from 0 to L, y from 0 to W and z from H/2 to H.', 'W_{e1}=\\frac12\\int_{H/2}^H\\!\\int_0^W\\!\\int_0^L\\epsilon_1\\frac{(V_1-V_0)^2}{L^2}\\,dx\\,dy\\,dz', []),
          S('被积函数为常数，三个积分给出 L、W、H/2。', 'The integrand is constant; the three integrals give L, W and H/2.', 'W_{e1}=\\frac12\\epsilon_1\\frac{(V_1-V_0)^2}{L^2}\\,LW\\frac H2=\\frac{\\epsilon_1HW}{4L}(V_1-V_0)^2', []),
          S('区域 2 只改变介电常数和 z 的积分范围；同样得到一半板间体积。', 'Region 2 changes only the permittivity and z bounds; its volume is the other half of the gap.', 'W_{e2}=\\frac12\\int_0^{H/2}\\!\\int_0^W\\!\\int_0^L\\epsilon_2\\frac{(V_1-V_0)^2}{L^2}\\,dx\\,dy\\,dz=\\frac{\\epsilon_2HW}{4L}(V_1-V_0)^2', []),
          S('提取两项的公因子并相加。', 'Factor the common terms and add both contributions.', 'W_e=\\frac{(\\epsilon_1+\\epsilon_2)HW}{4L}(V_1-V_0)^2', [])],r'W_e=\frac{(\epsilon_1+\epsilon_2)HW}{4L}(V_1-V_0)^2',4,5),
        P('c',2,'由能量求电容。','Find the capacitance from stored energy.',[
          S('原表给出电容器储能与电压的关系，这里的电压是两板电势差。', 'Use the crib capacitor-energy relation, with voltage equal to the plate potential difference.', 'W_e=\\frac12C(\\Delta V)^2,\\qquad\\Delta V=V_1-V_0', ['energy']),
          S('将上问求出的总能量完整代入，而不是直接使用平行板电容结论。', 'Substitute the full energy found above rather than jumping to a parallel-plate capacitance formula.', '\\frac12C(V_1-V_0)^2=\\frac{(\\epsilon_1+\\epsilon_2)HW}{4L}(V_1-V_0)^2', []),
          S('两边乘 2 并约去电势差的平方；零电压的情形由同一线性电容关系延续得到。', 'Multiply by two and cancel the squared potential difference. The zero-voltage case follows from the same linear capacitance relation.', 'C=\\frac{2}{(V_1-V_0)^2}\\frac{(\\epsilon_1+\\epsilon_2)HW}{4L}(V_1-V_0)^2', []),
          S('化简系数，并检查量纲为 F。', 'Simplify the coefficient and check that the dimension is farads.', 'C=\\frac{(\\epsilon_1+\\epsilon_2)HW}{2L}', [])],r'C=\frac{(\epsilon_1+\epsilon_2)HW}{2L}',5,6),
        P('d',2,'Bonus：该结果是否符合电容并联规律？','Bonus: does this agree with parallel-capacitor addition?',[
          S('从电容定义出发；并联等效的条件是两个区域连接同一对等势板。', 'Begin with the definition of capacitance. The two regions share the same pair of equipotential plates, so they have the same voltage.', 'C_i=\\frac{Q_i}{\\Delta V},\\qquad \\Delta V_1=\\Delta V_2=\\Delta V', ['capacitance']),
          S('两区域各占 H/2 的高度，面积均为 HW/2；场方向上的板间距都是 L。', 'Each region occupies half the height, so each area is HW/2 and both field-direction gaps are L.', 'A_1=A_2=\\frac{HW}{2},\\qquad C_1=\\frac{\\epsilon_1HW}{2L},\\quad C_2=\\frac{\\epsilon_2HW}{2L}', []),
          S('同一板上的两部分电荷相加，把 Qᵢ=CᵢΔV 逐项代入。', 'Add the two charge contributions on a plate and substitute Qᵢ=CᵢΔV.', 'Q=Q_1+Q_2=C_1\\Delta V+C_2\\Delta V=(C_1+C_2)\\Delta V', []),
          S('除以共同电压，即得到与能量法相同的并联结果。', 'Divide by the common voltage to recover the same parallel result as the energy method.', 'C=C_1+C_2', [])],r'C=C_1+C_2',5,6,answerText=L('是，两区域等效并联。Bonus 不计入试卷标称 42 分。','Yes: the regions are in parallel. The bonus is excluded from the exam’s stated 42 points.'))
      ])

    coax=Q(f,3,'从 Laplace 到同轴电容','From Laplace to coaxial capacitance',('拉普拉斯方程 · 电容','Laplace’s equation · capacitance'),
      (r'内导体半径 $a$ 且接地，外导体半径 $b$ 且电位为 $-V_0$。介质区 $a<r<b$ 无自由体电荷，介电常数为 $\epsilon$。先解电势，再求电位移、面电荷与单位长度电容。',
       r'The inner conductor of radius $a$ is grounded; the outer conductor of radius $b$ is at $-V_0$. The dielectric $a<r<b$ has permittivity $\epsilon$ and no free volume charge. Solve for potential, displacement, surface charge and capacitance per length.'),
      [r'V(a)=0',r'V(b)=-V_0',r'\rho=0'],12,6,[.34,.175,.32,.175],
      [R(13,19,'柱坐标 Laplace 方程','Cylindrical Laplace equation'),R(12,32,'同轴电容推导','Coaxial capacitance')],[
        P('a',6,'用 Laplace 或 Poisson 方程求 $V(r)$。','Use Laplace’s or Poisson’s equation to determine $V(r)$.',[
          S('先写原表的 Laplace 方程。介质中没有自由体电荷，所以 Poisson 方程的右侧为零。', 'Begin with the crib Laplace equation. With no free volume charge, the right side of Poisson’s equation vanishes.', '\\nabla^2V=0', ['laplace', 'poisson']),
          S('忽略端部效应，柱对称使电位只依赖 r，φ 与 z 的导数项都为零。', 'Neglecting end effects, cylindrical symmetry makes V depend only on r; the φ and z derivative terms vanish.', '\\nabla^2V=\\frac1r\\frac{d}{dr}\\left(r\\frac{dV}{dr}\\right)=0', []),
          S('乘以 r 并积分一次，把第一个积分常数记为 A。', 'Multiply by r and integrate once, calling the first constant A.', '\\frac{d}{dr}\\left(r\\frac{dV}{dr}\\right)=0\\quad\\Longrightarrow\\quad r\\frac{dV}{dr}=A', []),
          S('除以 r 再积分一次；用无量纲 r/a 写对数，第二个常数记为 B。', 'Divide by r and integrate again. Use dimensionless r/a in the logarithm and call the second constant B.', '\\frac{dV}{dr}=\\frac Ar\\quad\\Longrightarrow\\quad V(r)=A\\ln(r/a)+B', []),
          S('先代入内导体接地边界，解出 B。', 'Apply the grounded inner-conductor boundary first to determine B.', 'V(a)=A\\ln1+B=0\\quad\\Longrightarrow\\quad B=0', []),
          S('再代入外导体电位，解出 A。', 'Apply the outer-conductor potential next to determine A.', 'V(b)=A\\ln(b/a)=-V_0\\quad\\Longrightarrow\\quad A=-\\frac{V_0}{\\ln(b/a)}', []),
          S('把两个常数代回通解；在 a 和 b 分别得到 0 与 −V₀。', 'Substitute both constants into the general solution; the boundary values are 0 at a and −V₀ at b.', 'V(r)=-V_0\\frac{\\ln(r/a)}{\\ln(b/a)}', [])],r'V(r)=-V_0\frac{\ln(r/a)}{\ln(b/a)}',6,7),
        P('b',2,r'求介质区的 $\mathbf D(r)$。',r'Find $\mathbf D(r)$ in the dielectric.',[
          S('先写原表的梯度关系与本构关系。', 'Begin with the crib gradient and constitutive relations.', '\\mathbf E=-\\nabla V,\\qquad \\mathbf D=\\epsilon\\mathbf E', ['gradient', 'constitutive']),
          S('电位只依赖 r，梯度只保留径向分量。', 'The potential depends only on r, so retain only the radial gradient component.', '\\mathbf E=-\\frac{dV}{dr}\\hat{\\mathbf r}', []),
          S('把上问的 V(r) 代入，保留外侧负号。', 'Substitute the preceding V(r), keeping the leading minus sign.', '\\mathbf E=-\\frac d{dr}\\left[-\\frac{V_0}{\\ln(b/a)}\\ln(r/a)\\right]\\hat{\\mathbf r}', []),
          S('对 ln(r/a) 求导为 1/r，两个负号抵消。', 'The derivative of ln(r/a) is 1/r, and the two minus signs cancel.', '\\mathbf E=\\frac{V_0}{\\ln(b/a)}\\frac1r\\hat{\\mathbf r}', []),
          S('最后乘以介电常数，得到 D；V₀>0 时方向由内导体指向外导体。', 'Multiply by permittivity to obtain D, pointing from the inner toward the outer conductor when V₀>0.', '\\mathbf D(r)=\\frac{\\epsilon V_0}{r\\ln(b/a)}\\hat{\\mathbf r}', [])],r'\mathbf D(r)=\frac{\epsilon V_0}{r\ln(b/a)}\hat{\mathbf r}',7),
        P('c',2,'求两导体面电荷密度。','Find the surface charge densities on both conductors.',[
          S('从法向 D 的跳变条件开始。导体内部静电场为零，因此表面电荷由介质侧的法向 D 决定。', 'Start with the normal-D jump condition. The electrostatic field inside a conductor is zero, leaving the dielectric-side normal D.', 'D_{1n}-D_{2n}=\\rho_s,\\qquad \\rho_s=\\mathbf D_{\\mathrm{dielectric}}\\cdot\\hat{\\mathbf n}_{\\mathrm{out}}', ['boundary']),
          S('内导体朝向介质的外法向为 +r̂；将上问的 D 取在 a⁺。', 'The inner conductor’s normal into the dielectric is +r̂. Evaluate the preceding D at a⁺.', '\\hat{\\mathbf n}_a=+\\hat{\\mathbf r},\\qquad \\rho_{sa}=\\frac{\\epsilon V_0}{a\\ln(b/a)}(\\hat{\\mathbf r}\\cdot\\hat{\\mathbf r})', []),
          S('外导体的内表面朝向介质的法向为 −r̂；取 b⁻ 后点积产生负号。', 'At the outer conductor’s inner surface the normal into the dielectric is −r̂. Evaluating at b⁻ therefore introduces a minus sign.', '\\hat{\\mathbf n}_b=-\\hat{\\mathbf r},\\qquad \\rho_{sb}=\\frac{\\epsilon V_0}{b\\ln(b/a)}(\\hat{\\mathbf r}\\cdot[-\\hat{\\mathbf r}])', []),
          S('作为核对，两柱面的每单位长度电荷相加为零，而不是两处面密度数值相反。', 'Check that the charges per unit length cancel; the two surface densities themselves need not have equal magnitudes.', '2\\pi a\\rho_{sa}+2\\pi b\\rho_{sb}=0', []),
          S('写出两个表面电荷密度，单位均为 C/m²。', 'State both surface charge densities, each in C/m².', '\\rho_{sa}=\\frac{\\epsilon V_0}{a\\ln(b/a)},\\quad\\rho_{sb}=-\\frac{\\epsilon V_0}{b\\ln(b/a)}', [])],r'\rho_{sa}=\frac{\epsilon V_0}{a\ln(b/a)},\quad\rho_{sb}=-\frac{\epsilon V_0}{b\ln(b/a)}',7,7),
        P('d',2,r'求单位长度电容 $C^\prime$。',r'Find capacitance per unit length $C^\prime$.',[
          S('先写电容定义，并明确分母是两导体之间的电势差。', 'Begin with the capacitance definition, using the potential difference between conductors.', 'C=\\frac Q{\\Delta V},\\qquad\\Delta V=V(a)-V(b)=V_0', ['capacitance', 'potential']),
          S('取任意长度 ℓ 的内导体，柱面面积为 2πaℓ，均匀面密度可移出积分。', 'Take an inner-conductor segment of arbitrary length ℓ. Its cylindrical area is 2πaℓ and the surface density is uniform.', 'Q=\\int_0^\\ell\\!\\int_0^{2\\pi}\\rho_{sa}a\\,d\\phi\\,dz=2\\pi a\\ell\\rho_{sa}', ['geometry']),
          S('代入上问的面密度，再除以长度，得到每单位长度电荷。', 'Substitute the surface density and divide by length to obtain charge per unit length.', 'Q^\\prime=\\frac Q\\ell=2\\pi a\\frac{\\epsilon V_0}{a\\ln(b/a)}=\\frac{2\\pi\\epsilon V_0}{\\ln(b/a)}', []),
          S('对每单位长度使用同一电容定义，约去电压 V₀。', 'Use the same definition per unit length and cancel V₀.', 'C^\\prime=\\frac{Q^\\prime}{V_0}=\\frac{2\\pi\\epsilon V_0}{V_0\\ln(b/a)}', []),
          S('所得量纲为 F/m。', 'The resulting dimension is F/m.', 'C^\\prime=\\frac{2\\pi\\epsilon}{\\ln(b/a)}\\quad[\\mathrm{F/m}]', [])],r'C^\prime=\frac{2\pi\epsilon}{\ln(b/a)}\quad[\mathrm{F/m}]',7,8)
      ])

    dipole=Q(f,4,'带电球的电场叠加','Superposition of charged-sphere fields',('库仑定律 · 矢量叠加','Coulomb’s law · superposition'),
      ('两个半径为 $a$ 的球分别位于 $(-d,0,0)$ 与 $(d,0,0)$，总电荷分别为 $+Q$ 和 $-Q$。观察点为 $P=(0,0,z)$。按原解所采用的球对称等效点电荷模型求解。',
       'Two spheres of radius $a$ are centered at $(-d,0,0)$ and $(d,0,0)$ with charges $+Q$ and $-Q$. The observation point is $P=(0,0,z)$. Use the spherically symmetric equivalent point-charge model used by the official solution.'),
      [r'\mathbf r_+=(-d,0,0)',r'\mathbf r_-=(d,0,0)',r'P=(0,0,z)'],10,8,[.25,.16,.50,.24],
      [R(10,7,'库仑定律与叠加','Coulomb’s law and superposition'),R(11,9,'路径无关与电势','Path independence and potential')],[
        P('a',2,'先求原点处单个带电球在 $r>a$ 的电场。','Find the field outside one charged sphere centered at the origin.',[
          S('先写高斯定律，取包围孤立导体球的同心球面，半径 R>a。', 'Begin with Gauss’s law on a concentric sphere of radius R>a enclosing the isolated conducting sphere.', '\\oiint_{S_R}\\mathbf D\\cdot d\\mathbf S=Q_{\\mathrm{enc}}=Q', ['gauss']),
          S('由球对称性，代入径向电场、本构关系和面积元。', 'By spherical symmetry, substitute the radial field, constitutive relation and surface element.', '\\Phi_D=\\int_0^{2\\pi}\\!\\int_0^\\pi(\\epsilon_0E_r(R)\\hat{\\mathbf r})\\cdot(\\hat{\\mathbf r}R^2\\sin\\theta)\\,d\\theta d\\phi', ['constitutive', 'geometry']),
          S('点积为 1，两个角积分分别为 2π 和 2。', 'The unit-vector dot product is one and the angular integrals are 2π and 2.', '\\Phi_D=4\\pi\\epsilon_0R^2E_r(R)=Q', []),
          S('两边除以球面积和介电常数，再把 R 改记为观察半径 r。', 'Divide by spherical area and permittivity, then relabel R as observation radius r.', '\\mathbf E=\\frac{Q}{4\\pi\\epsilon_0r^2}\\hat{\\mathbf r}', [])],r'\mathbf E=\frac{Q}{4\pi\epsilon_0r^2}\hat{\mathbf r}',8,9),
        P('b',4,'求 P 点的总电场，用直角坐标表示。','Find the total field at P in Cartesian coordinates.',[
          S('从库仑定律和叠加原理出发。按官方解采用各球等效为球心点电荷的近似。', 'Start with Coulomb’s law and superposition, using the official approximation that each sphere acts as a point charge at its center.', '\\mathbf E_i(P)=\\frac{q_i}{4\\pi\\epsilon_0}\\frac{\\mathbf R_i}{|\\mathbf R_i|^3},\\qquad\\mathbf E_{\\mathrm{tot}}=\\sum_i\\mathbf E_i', ['coulomb']),
          S('先写两个球心和观察点，再逐项相减得到从电荷到观察点的位移。', 'Write both centers and the observation point, then subtract each center from P.', '\\begin{aligned}\\mathbf r_+&=(-d,0,0),&\\mathbf R_+&=(d,0,z)\\\\\\mathbf r_-&=(d,0,0),&\\mathbf R_-&=(-d,0,z)\\end{aligned}', []),
          S('两个距离相同。将正电荷 +Q 及其位移代入。', 'The distances agree. Substitute +Q and its displacement first.', '|\\mathbf R_+|=|\\mathbf R_-|=\\sqrt{d^2+z^2},\\qquad\\mathbf E_+=\\frac{Q(d\\hat{\\mathbf x}+z\\hat{\\mathbf z})}{4\\pi\\epsilon_0(d^2+z^2)^{3/2}}', []),
          S('负电荷必须连同自身符号代入；其 x 分量为正、z 分量与正电荷的相反。', 'Include the negative charge sign explicitly; its x component is positive and its z component opposes that of +Q.', '\\mathbf E_-=\\frac{(-Q)(-d\\hat{\\mathbf x}+z\\hat{\\mathbf z})}{4\\pi\\epsilon_0(d^2+z^2)^{3/2}}=\\frac{Q(d\\hat{\\mathbf x}-z\\hat{\\mathbf z})}{4\\pi\\epsilon_0(d^2+z^2)^{3/2}}', []),
          S('逐分量相加：z 分量抵消，x 分量为两倍。', 'Add components: the z components cancel and the x components double.', '\\mathbf E_{\\mathrm{tot}}=\\frac{Q[(d+d)\\hat{\\mathbf x}+(z-z)\\hat{\\mathbf z}]}{4\\pi\\epsilon_0(d^2+z^2)^{3/2}}', []),
          S('化简为题目要求的笛卡尔坐标形式。', 'Simplify to the requested Cartesian vector form.', '\\mathbf E_{\\mathrm{tot}}=\\frac{Qd}{2\\pi\\epsilon_0(d^2+z^2)^{3/2}}\\hat{\\mathbf x}', [])],r'\mathbf E_{\mathrm{tot}}=\frac{Qd}{2\pi\epsilon_0(d^2+z^2)^{3/2}}\hat{\mathbf x}',8,9),
        P('c',1,'在 P 放置试探电荷 $-Q$，求它受到的力。','Place a test charge $-Q$ at P and find its force.',[
          S('先写点电荷受力公式，使用前一问中两个源电荷产生的外场。', 'Begin with the force on a point charge, using the external field from the two source charges.', '\\mathbf F=q_{\\mathrm{test}}\\mathbf E_{\\mathrm{ext}}', ['coulomb']),
          S('题目放入的试探电荷是 −Q，不能只代入正的电荷大小。', 'The inserted test charge is −Q; retain its sign rather than using only its magnitude.', 'q_{\\mathrm{test}}=-Q,\\qquad\\mathbf E_{\\mathrm{ext}}=\\frac{Qd}{2\\pi\\epsilon_0(d^2+z^2)^{3/2}}\\hat{\\mathbf x}', []),
          S('完整相乘，电荷因子变为 −Q²。按题目采用既定外场，不另计算试探电荷引起的球面电荷重分布。', 'Multiply explicitly to obtain −Q². Follow the specified external-field model without adding redistribution of the conducting-sphere charges.', '\\mathbf F=(-Q)\\frac{Qd}{2\\pi\\epsilon_0(d^2+z^2)^{3/2}}\\hat{\\mathbf x}', []),
          S('力沿 −x 方向。', 'The force points along −x.', '\\mathbf F=-\\frac{Q^2d}{2\\pi\\epsilon_0(d^2+z^2)^{3/2}}\\hat{\\mathbf x}', [])],r'\mathbf F=-\frac{Q^2d}{2\pi\epsilon_0(d^2+z^2)^{3/2}}\hat{\mathbf x}',9,10),
        P('d',2,'建立从 O=(0,0,0) 到 P 的电势差积分。','Set up the potential-difference integral from O=(0,0,0) to P.',[
          S('先写两端点电势差的线积分原式。', 'Begin with the line integral for the potential difference between the endpoints.', 'V(P)-V(O)=-\\int_O^P\\mathbf E\\cdot d\\mathbf l', ['potential']),
          S('选择题目两点之间的 z 轴直线路径，用 ζ 作为积分变量，z 保留给终点。', 'Choose the straight z-axis path. Use ζ as the integration variable and reserve z for the endpoint.', '\\mathbf r(\\zeta)=(0,0,\\zeta),\\quad 0\\le\\zeta\\le z,\\quad d\\mathbf l=\\hat{\\mathbf z}\\,d\\zeta', []),
          S('把沿路径的电场代入；它始终只有 x 分量。题目只要求列式，到这里即可给出完整积分。', 'Substitute the field along the path, which has only an x component. This already provides the complete integral requested.', 'V(P)-V(O)=-\\int_0^z\\frac{Qd\\hat{\\mathbf x}}{2\\pi\\epsilon_0(d^2+\\zeta^2)^{3/2}}\\cdot\\hat{\\mathbf z}\\,d\\zeta', []),
          S('额外核对：x̂·ẑ=0，所以积分的被积函数处处为零。', 'As a check, x̂·ẑ=0, making the integrand zero everywhere.', 'V(P)-V(O)=-\\int_0^z\\frac{Qd\\,\\hat{\\mathbf x}\\cdot\\hat{\\mathbf z}}{2\\pi\\epsilon_0(d^2+\\zeta^2)^{3/2}}\\,d\\zeta=0', [])],r'V(P)-V(O)=-\int_0^z\frac{Qd\,\hat{\mathbf x}\cdot\hat{\mathbf z}}{2\pi\epsilon_0(d^2+\zeta^2)^{3/2}}\,d\zeta=0',9,10),
        P('e',1,'静电势差是否依赖积分路径？用 Maxwell 方程解释。','Does the electrostatic potential difference depend on path? Explain with Maxwell’s equation.',[
          S('先写静电场的 Maxwell–Faraday 方程：闭合路径上的环流为零。', 'Begin with the electrostatic Maxwell–Faraday equation: circulation around a closed path is zero.', '\\oint\\mathbf E\\cdot d\\mathbf l=0,\\qquad\\nabla\\times\\mathbf E=0', ['conservative']),
          S('取两条由同一起点 A 到同一终点 B 的路径 C₁、C₂，将第二条反向后闭合。', 'Take two paths C₁ and C₂ from the same A to the same B; reverse the second to form a closed loop.', '0=\\oint_{C_1-C_2}\\mathbf E\\cdot d\\mathbf l=\\int_{C_1}\\mathbf E\\cdot d\\mathbf l-\\int_{C_2}\\mathbf E\\cdot d\\mathbf l', []),
          S('移项表明两条路径的积分相等，再乘电势定义中的负号。', 'Rearrange to show equal path integrals, then apply the minus sign in the potential definition.', '-\\int_{C_1}\\mathbf E\\cdot d\\mathbf l=-\\int_{C_2}\\mathbf E\\cdot d\\mathbf l=V(B)-V(A)', ['potential']),
          S('因此静电电势差只由端点决定；允许选择使点积最简单的路径。', 'The electrostatic potential difference therefore depends only on the endpoints; choose a path that simplifies the dot product.', '\\Delta V\\ \\text{is path independent}', [])],r'\Delta V\ \text{is path independent}',9,10,answerText=L('不依赖路径，只依赖端点。','It depends only on the endpoints.'))
      ],note=L('适用范围：两个真实导体球会相互极化，严格外场一般不等于球心点电荷叠加。这里沿用原卷模型；相距很远 a≪d 时可作近似。','Model limitation: real conducting spheres polarize one another, so their exact fields are not generally center-point-charge fields. This follows the exam model; it is a useful approximation when a≪d.'))

    microstrip=Q(s,1,'高频微带线的电阻','Resistance of a high-frequency microstrip',('电流密度 · 电阻','Current density · resistance'),
      (r'无限长微带线沿 $x$ 方向，宽 $W$、厚 $h$、电导率 $\sigma$。电流仅流过上下表面各 $0.1h$ 厚的层，层内 $\mathbf J=J_0\hat{\mathbf x}$，中间为零。忽略边缘效应，按试卷的有效导电截面模型求解。',
       r'An infinite microstrip runs along x, with width $W$, thickness $h$ and conductivity $\sigma$. Current flows only in two surface layers, each of thickness $0.1h$, where $\mathbf J=J_0\hat{\mathbf x}$; it is zero in the middle. Neglect fringing and use the exam’s effective conducting-area model.'),
      [r'0.4h\le |z|\le0.5h',r'\mathbf J=J_0\hat{\mathbf x}',r'A_{\mathrm{eff}}=0.2Wh'],6,2,[.45,.125,.44,.30],
      [R(14,9,'电流密度的通量积分','Current as a flux integral'),R(14,14,'趋肤效应与非均匀电流','Skin effect and nonuniform current')],[
        P('a',0,'求流过微带线的总电流 I。','Find total current I through the microstrip.',[
          S('先写公式表中的电流密度通量公式，总电流是穿过截面的 J 的法向分量积分。', 'Begin with the crib current-density flux equation: integrate the normal component of J over the cross-section.', 'I=\\iint_S\\mathbf J\\cdot d\\mathbf S', ['current']),
          S('电流沿 +x，所以选 yz 截面、外法向 +x̂；按原图 y 从 0 到 W，z 从 −0.5h 到 0.5h。', 'Current flows along +x, so choose a yz cross-section with normal +x̂. As drawn, y runs from 0 to W and z from −0.5h to 0.5h.', 'd\\mathbf S=\\hat{\\mathbf x}\\,dy\\,dz,\\qquad \\hat{\\mathbf x}\\cdot\\hat{\\mathbf x}=1', []),
          S('将分段电流密度逐段代入。中间层 J=0，只有上下两层贡献。', 'Substitute the piecewise current density. The middle has J=0, leaving the lower and upper layers.', '\\begin{aligned}I={}&\\int_{-0.5h}^{-0.4h}\\!\\int_0^W J_0\\,dy\\,dz\\\\&+\\int_{0.4h}^{0.5h}\\!\\int_0^W J_0\\,dy\\,dz\\end{aligned}', []),
          S('先对 y 积分得到 W，再代入两段 z 的上下限。', 'Integrate over y to obtain W, then evaluate both z intervals.', 'I=J_0W\\bigl[(-0.4h)-(-0.5h)\\bigr]+J_0W\\bigl[(0.5h)-(0.4h)\\bigr]', []),
          S('每层厚度是 0.1h，总载流面积为 0.2Wh；电流量纲为 A。', 'Each layer is 0.1h thick, giving total conducting area 0.2Wh and current in amperes.', 'I=J_0W(0.1h+0.1h)=0.2J_0Wh', [])],r'I=0.2J_0Wh',2),
        P('b',0,r'求单位长度电势降的大小 $V^\prime$。',r'Find the magnitude of potential drop per unit length $V^\prime$.',[
          S('先写电势差原式与微观欧姆定律。题目要求电压降的大小，符号约定应先明确。', 'Begin with the potential integral and microscopic Ohm’s law. Define the voltage-drop sign before taking its magnitude.', 'V(B)-V(A)=-\\int_A^B\\mathbf E\\cdot d\\mathbf l,\\qquad\\mathbf J=\\sigma\\mathbf E', ['potential', 'ohm']),
          S('沿题设承载电流的表层取一条 x 方向路径；这一层的电场由 J₀/σ 给出。', 'Choose an x-directed path in a current-carrying surface layer. Its electric field follows from J₀/σ.', '\\mathbf E=\\frac{\\mathbf J}{\\sigma}=\\frac{J_0}{\\sigma}\\hat{\\mathbf x},\\qquad d\\mathbf l=\\hat{\\mathbf x}\\,dx', []),
          S('在长度 ℓ 上代入积分并计算单位矢量点积。', 'Substitute into the integral over a length ℓ and evaluate the unit-vector dot product.', 'V(\\ell)-V(0)=-\\int_0^\\ell\\frac{J_0}{\\sigma}(\\hat{\\mathbf x}\\cdot\\hat{\\mathbf x})\\,dx', []),
          S('场强沿 x 不变，积分给出 ℓ。沿电流方向电位降低，因此电压降大小为正。', 'The field is independent of x, so integration gives ℓ. Potential decreases along the current, making the drop magnitude positive.', 'V(0)-V(\\ell)=\\frac{J_0\\ell}{\\sigma},\\qquad V^\\prime=\\frac{|V(0)-V(\\ell)|}{\\ell}', []),
          S('除以长度 ℓ，单位由 V 变为 V/m。', 'Divide by ℓ to obtain volts per meter.', 'V^\\prime=\\frac{J_0}{\\sigma}', [])],r'V^\prime=\frac{J_0}{\sigma}\quad[\mathrm{V/m}]',2),
        P('c',0,r'求单位长度电阻 $R^\prime$。',r'Find resistance per unit length $R^\prime$.',[
          S('先写电阻定义，再将其除以导线长度，得到单位长度形式。', 'Begin with the resistance definition and divide by conductor length to obtain its per-length form.', 'R=\\frac{\\Delta V}{I},\\qquad R^\\prime=\\frac R\\ell=\\frac{\\Delta V/\\ell}{I}=\\frac{V^\\prime}{I}', ['resistance']),
          S('把 a)、b) 的两个结果完整代入，不要把电压降和总电压混淆。', 'Substitute both preceding results explicitly, distinguishing voltage drop per length from total voltage.', 'I=0.2J_0Wh,\\qquad V^\\prime=\\frac{J_0}{\\sigma},\\qquad R^\\prime=\\frac{J_0/\\sigma}{0.2J_0Wh}', []),
          S('约去电流密度 J₀，将 1/0.2 化为 5。', 'Cancel J₀ and evaluate 1/0.2 as 5.', 'R^\\prime=\\frac1{0.2\\sigma Wh}=\\frac5{\\sigma Wh}', []),
          S('检查单位：(S/m)·m²= S·m，取倒数得到 Ω/m。', 'Check units: (S/m)·m² is S·m, whose reciprocal is Ω/m.', 'R^\\prime=\\frac{5}{\\sigma Wh}\\quad[\\Omega/\\mathrm m]', [])],r'R^\prime=\frac{5}{\sigma Wh}\quad[\Omega/\mathrm m]',3),
        P('d',0,'同样的电流密度下，为什么提高 σ 会降低电阻？','At the same current density, why does increasing σ reduce resistance?',[
          S('先用微观欧姆定律明确哪些量固定：题目保持同一个 J(z) 分布和同一截面。', 'Use microscopic Ohm’s law to identify what stays fixed: the specified J(z) distribution and conductor cross-section.', '\\mathbf J=\\sigma\\mathbf E,\\qquad I=\\iint\\mathbf J\\cdot d\\mathbf S', ['ohm', 'current']),
          S('固定电流密度与面积意味着总电流也不变。提高 σ 后，同一 J 所需的驱动电场更小。', 'Fixed current density and area keep total current unchanged. Increasing σ requires less driving field for that same J.', 'I=0.2J_0Wh=\\text{constant},\\qquad E_x=\\frac{J_0}{\\sigma}', []),
          S('长度相同，电场减小会让单位长度电压降减小；把它代入电阻定义。', 'For the same length, a smaller field gives a smaller voltage drop per length. Substitute that into the resistance definition.', 'R^\\prime=\\frac{V^\\prime}{I}=\\frac{J_0/\\sigma}{0.2J_0Wh}=\\frac5{\\sigma Wh}', ['resistance']),
          S('因此增加电导率会降低电阻；原因是维持相同电流所需的电压降减少。', 'Increasing conductivity therefore reduces resistance because the same current requires a smaller voltage drop.', '\\sigma\\uparrow\\ \\Longrightarrow\\ R^\\prime\\downarrow', [])],r'\sigma\uparrow\ \Longrightarrow\ R^\prime\downarrow',3,answerText=L('更高电导率意味着维持同样电流只需更小的驱动电场。','Higher conductivity requires a smaller driving field for the same current.')),
        P('e',0,'同样总电流若均匀流过整个截面，电阻如何变化？','For the same total current, how does resistance change if current fills the entire cross-section uniformly?',[
          S('先写电流积分和欧姆定律。这次固定的是总电流 I，而不是原来的表层密度 J₀。', 'Begin with the current integral and Ohm’s law. Here total current I is fixed, rather than the previous surface-layer density J₀.', 'I=\\iint\\mathbf J\\cdot d\\mathbf S,\\qquad\\mathbf E=\\frac{\\mathbf J}{\\sigma}', ['current', 'ohm']),
          S('均匀分布使用整个 Wh 截面；先求新的电流密度。', 'A uniform distribution uses the entire Wh cross-section. Compute the new current density first.', 'J_{\\mathrm{uniform}}=\\frac I{Wh}=\\frac{0.2J_0Wh}{Wh}=0.2J_0', []),
          S('代入欧姆定律，电场与每单位长度电压降都变为原来的五分之一。', 'Substitute into Ohm’s law: both field and voltage drop per length become one fifth of their previous values.', 'E_{\\mathrm{uniform}}=\\frac{0.2J_0}{\\sigma}=0.2E_{\\mathrm{skin}},\\qquad V^\\prime_{\\mathrm{uniform}}=0.2V^\\prime_{\\mathrm{skin}}', []),
          S('总电流保持不变，将电压降比代入 R′=V′/I。', 'With total current unchanged, insert this voltage-drop ratio into R′=V′/I.', 'R^\\prime_{\\mathrm{uniform}}=\\frac{I/(\\sigma Wh)}{I}=\\frac1{\\sigma Wh},\\qquad R^\\prime_{\\mathrm{skin}}=\\frac5{\\sigma Wh}', ['resistance']),
          S('得到电阻减为五分之一，即下降 80%；物理原因是可供载流的有效面积扩大。', 'Resistance becomes one fifth, an 80% reduction, because the available current-carrying area increases.', 'R^\\prime_{\\mathrm{uniform}}=\\frac15 R^\\prime_{\\mathrm{skin}}', [])],r'R^\prime_{\mathrm{uniform}}=\frac15 R^\prime_{\mathrm{skin}}',3)
      ],caption=('上下橙色薄层承载电流；中间区域 J=0。横截面与电流分布均按题设绘制。','Orange surface layers carry current; the central region has J=0. Cross-section and profile follow the given distribution.'))

    boundary=Q(s,2,'三层介质的边界条件','Boundary conditions across three dielectrics',('边界条件 · 极化','Boundary conditions · polarization'),
      (r'介质 1 位于 $y>0.01\,\mathrm m$，$\epsilon_1=2\epsilon_0$；介质 2 位于 $0<y<0.01\,\mathrm m$，$\epsilon_2=5\epsilon_0$；介质 3 位于 $y<0$，$\epsilon_3=2\epsilon_0$。分界面无自由面电荷。',
       r'Dielectric 1 occupies $y>0.01\,\mathrm m$ with $\epsilon_1=2\epsilon_0$; dielectric 2 occupies $0<y<0.01\,\mathrm m$ with $\epsilon_2=5\epsilon_0$; dielectric 3 occupies $y<0$ with $\epsilon_3=2\epsilon_0$. There is no free interfacial surface charge.'),
      [r'\mathbf E_1=(100\hat{\mathbf x}-100\hat{\mathbf y})\,\mathrm{V/m}',r'\rho_s=0',r'd=0.01\,\mathrm m'],8,4,[.25,.20,.50,.25],
      [R(12,14,'切向电场连续','Tangential electric field'),R(12,15,'法向电位移边界条件','Normal displacement boundary condition'),R(11,22,'介质极化','Dielectric polarization')],[
        P('a',0,'求介质 2 内的电场。','Find the field in dielectric 2.',[
          S('先写原表的两条静电边界条件和本构关系。', 'Begin with both crib electrostatic boundary conditions and the constitutive relation.', 'D_{1n}-D_{2n}=\\rho_s,\\quad E_{1t}=E_{2t},\\quad\\mathbf D_i=\\epsilon_i\\mathbf E_i', ['boundary', 'constitutive']),
          S('分界面是 y=0.01 m，法向沿 y、切向沿 x。先将已知电场分解。', 'The interface is y=0.01 m, with normal along y and tangent along x. Decompose the given field.', 'E_{1t}=E_{1x}=100\\,\\mathrm{V/m},\\quad E_{1n}=E_{1y}=-100\\,\\mathrm{V/m},\\quad E_{1z}=0', []),
          S('切向 E 连续，因此 x 分量直接传递，z 分量仍为零。', 'Tangential E is continuous, so the x component carries across and the z component remains zero.', 'E_{2x}=E_{1x}=100\\,\\mathrm{V/m},\\qquad E_{2z}=0', []),
          S('无自由面电荷，令法向 D 的跳变为零，再解出 E₂y。', 'There is no free surface charge. Set the normal-D jump to zero and solve for E₂y.', '\\epsilon_1E_{1y}-\\epsilon_2E_{2y}=0\\quad\\Longrightarrow\\quad E_{2y}=\\frac{\\epsilon_1}{\\epsilon_2}E_{1y}', []),
          S('代入两个介电常数，约去 ε₀，保留已知 y 分量的负号。', 'Insert both permittivities, cancel ε₀ and retain the negative y component.', 'E_{2y}=\\frac{2\\epsilon_0}{5\\epsilon_0}(-100)=-40\\,\\mathrm{V/m}', []),
          S('把三个分量合成为矢量。', 'Combine all three components into the vector.', '\\mathbf E_2=(100\\hat{\\mathbf x}-40\\hat{\\mathbf y})\\,\\mathrm{V/m}', [])],r'\mathbf E_2=(100\hat{\mathbf x}-40\hat{\mathbf y})\,\mathrm{V/m}',4),
        P('b',0,'求介质 3 内的电场。','Find the field in dielectric 3.',[
          S('在 y=0 的第二个介质界面再次使用切向 E 连续和法向 D 连续。', 'At the second dielectric interface y=0, again use continuity of tangential E and normal D.', 'E_{2t}=E_{3t},\\qquad D_{2n}-D_{3n}=0', ['boundary']),
          S('上问给出 E₂x=100、E₂y=−40，法向和切向仍分别为 y 与 x。', 'The preceding result gives E₂x=100 and E₂y=−40; y remains normal and x tangential.', 'E_{3x}=E_{2x}=100\\,\\mathrm{V/m},\\qquad E_{3z}=0', []),
          S('先代入本构关系，再把 E₃y 单独移到一侧。', 'Substitute the constitutive relation and isolate E₃y.', '\\epsilon_2E_{2y}=\\epsilon_3E_{3y}\\quad\\Longrightarrow\\quad E_{3y}=\\frac{\\epsilon_2}{\\epsilon_3}E_{2y}', ['constitutive']),
          S('代入 ε₂=5ε₀、ε₃=2ε₀ 和 −40 V/m。', 'Substitute ε₂=5ε₀, ε₃=2ε₀ and −40 V/m.', 'E_{3y}=\\frac{5\\epsilon_0}{2\\epsilon_0}(-40)=-100\\,\\mathrm{V/m}', []),
          S('恢复完整矢量。因为 ε₃=ε₁，最终场与区域 1 一致。', 'Restore the complete vector. Since ε₃=ε₁, the field agrees with region 1.', '\\mathbf E_3=(100\\hat{\\mathbf x}-100\\hat{\\mathbf y})\\,\\mathrm{V/m}', [])],r'\mathbf E_3=(100\hat{\mathbf x}-100\hat{\mathbf y})\,\mathrm{V/m}',5),
        P('c',0,'求跨越介质 2 的电势差 $V_0=V(0.01)-V(0)$，保持 x 不变。','Find $V_0=V(0.01)-V(0)$ across dielectric 2 at fixed x.',[
          S('先明确电势差的次序，再写原表的负线积分。', 'Specify the order of the potential difference before writing the crib negative line integral.', 'V_0=V(y=0.01)-V(y=0)=-\\int_{y=0}^{y=0.01}\\mathbf E_2\\cdot d\\mathbf l', ['potential']),
          S('选 x、z 不变的直线路径，仅有 dy 分量。', 'Choose a straight path at fixed x and z, leaving only a dy component.', 'd\\mathbf l=\\hat{\\mathbf y}\\,dy,\\qquad \\mathbf E_2=(100\\hat{\\mathbf x}-40\\hat{\\mathbf y})\\,\\mathrm{V/m}', []),
          S('展开点积，x̂·ŷ=0，ŷ·ŷ=1，因此切向的 100 V/m 不参与本次电势差。', 'Expand the dot product: x̂·ŷ=0 and ŷ·ŷ=1, so the tangential 100 V/m does not contribute.', '\\mathbf E_2\\cdot d\\mathbf l=[100(0)-40(1)]\\,dy=-40\\,dy', []),
          S('积分常数场，并把 0.01 m 代入上下限；外面的负号使结果为正。', 'Integrate the constant field and substitute the 0.01 m limits. The leading minus sign makes the result positive.', 'V_0=-\\int_0^{0.01}(-40)\\,dy=40[\\,y\\,]_0^{0.01}=40(0.01)\\,\\mathrm V', []),
          S('所求电势差为 +0.40 V，表示上表面的电位较高。', 'The requested difference is +0.40 V, meaning the upper surface is at higher potential.', 'V_0=+0.40\\,\\mathrm V', [])],r'V_0=+0.40\,\mathrm V',5),
        P('d',0,'用极化解释介质 2 中场强为何较小。','Explain using polarization why the field magnitude in dielectric 2 is smaller.',[
          S('用边界条件和 D=εE 作为解释起点；不是把全部电场都按 1/ε 缩放。', 'Start from the boundary conditions and D=εE. The entire field does not scale uniformly as 1/ε.', 'D_{1n}=D_{2n}=D_{3n},\\qquad E_{1t}=E_{2t}=E_{3t}', ['boundary', 'constitutive']),
          S('相同法向 D 下，介电常数最大的区域 2 具有最小的法向 E。', 'For the same normal D, region 2 has the smallest normal E because its permittivity is largest.', 'E_{2n}=\\frac{D_n}{5\\epsilon_0},\\qquad E_{1n}=E_{3n}=\\frac{D_n}{2\\epsilon_0}', []),
          S('材料中的电偶极被极化，其响应使给定自由电荷产生的法向净场减弱；切向场仍由连续条件限定。', 'Polarization of material dipoles reduces the normal net field for the given free charge, while tangential continuity constrains the tangential field.', '|E_{2n}|=40<100=|E_{1n}|=|E_{3n}|\\quad[\\mathrm{V/m}]', []),
          S('比较题目问到的总场大小，必须使用各分量平方和，而不是只比较 y 分量。', 'Compare total field magnitudes using the sum of squared components, rather than the y component alone.', '|\\mathbf E_2|=\\sqrt{100^2+40^2}\\approx107.7\\,\\mathrm{V/m},\\quad |\\mathbf E_1|=|\\mathbf E_3|=\\sqrt{100^2+100^2}\\approx141.4\\,\\mathrm{V/m}', []),
          S('因此区域 2 的总场较小，区域 1 和 3 的场强相同。', 'Region 2 therefore has the smaller total field, while regions 1 and 3 agree.', '|\\mathbf E_2|<|\\mathbf E_1|=|\\mathbf E_3|', [])],r'|\mathbf E_2|<|\mathbf E_1|=|\mathbf E_3|',5,answerText=L('减小的是法向分量；不能把所有电场分量都按介电常数反比缩放。','The normal component decreases; do not scale every field component inversely with permittivity.'))
      ])

    leaky=Q(s,3,'含空间电荷的同轴线','A coaxial line with space charge',('高斯定律 · 微分电容','Gauss’s law · differential capacitance'),
      (r'同轴线内导体半径 $a$、面电荷密度 $\rho_{sa}$；外壳半径 $b$ 且接地。介质区介电常数为 $\epsilon$，漏入的体电荷密度为 $\rho(r)=\rho_0a/r$。忽略端部效应。',
       r'A coaxial cable has inner radius $a$ and surface charge density $\rho_{sa}$, with a grounded outer shell of radius $b$. Its dielectric has permittivity $\epsilon$ and space-charge density $\rho(r)=\rho_0a/r$. Neglect end effects.'),
      [r'\rho(r)=\rho_0\frac ar',r'V(b)=0',r'a<r<b'],8,6,[.53,.11,.36,.22],
      [R(10,32,'柱对称高斯定律','Cylindrical Gauss’s law'),R(11,12,'由电场积分求电势','Integrating field to potential'),R(12,25,'微分电容定义','Differential capacitance')],[
        P('a',0,'用高斯定律求介质区电场，并画高斯面。','Use Gauss’s law to find the dielectric field and draw the Gaussian surface.',[
          S('先写原始高斯定律，再将电位移换成 εE。', 'Begin with the original Gauss equation and substitute εE for displacement.', '\\oiint_S\\mathbf D\\cdot d\\mathbf S=Q_{\\mathrm{enc}},\\qquad\\mathbf D=\\epsilon\\mathbf E', ['gauss', 'constitutive']),
          S('选半径 R、长度 ℓ 的同轴闭合圆柱，高斯半径满足 a<R<b；端面的法向与径向电场垂直。', 'Choose a coaxial closed cylinder of radius R and length ℓ, with a<R<b. End-cap normals are perpendicular to the radial field.', '\\mathbf E=E_r(R)\\hat{\\mathbf r},\\quad d\\mathbf S_{\\mathrm{side}}=\\hat{\\mathbf r}R\\,d\\phi\\,dz,\\quad \\mathbf E\\cdot d\\mathbf S_{\\mathrm{caps}}=0', ['geometry']),
          S('代入柱侧面通量积分，依次计算 φ 和 z 积分。', 'Substitute into the lateral-surface flux integral and evaluate the φ and z factors.', '\\Phi_D=\\int_0^\\ell\\!\\int_0^{2\\pi}\\epsilon E_r(R)R\\,d\\phi\\,dz=2\\pi R\\ell\\epsilon E_r(R)', []),
          S('包围电荷分成内导体表面电荷与 a 到 R 之间的体电荷。先积分内导体柱面。', 'Split enclosed charge into the inner-conductor surface charge and volume charge from a to R. Integrate the inner surface first.', 'Q_{\\mathrm{surface}}=\\int_0^\\ell\\!\\int_0^{2\\pi}\\rho_{sa}a\\,d\\phi\\,dz=2\\pi a\\ell\\rho_{sa}', []),
          S('体电荷积分必须使用变半径 r′；将密度 ρ₀a/r′ 和柱坐标体积元 r′dr′dφdz 同时代入。', 'For volume charge use a varying radius r′. Substitute both ρ₀a/r′ and the cylindrical volume element r′dr′dφdz.', 'Q_{\\mathrm{volume}}=\\int_0^\\ell\\!\\int_0^{2\\pi}\\!\\int_a^R\\frac{\\rho_0a}{r^\\prime}\\,r^\\prime\\,dr^\\prime d\\phi dz', []),
          S('密度中的 1/r′ 与体积元的 r′ 抵消，剩下常数的径向积分。', 'The density’s 1/r′ cancels the volume element’s r′, leaving a constant radial integral.', 'Q_{\\mathrm{volume}}=2\\pi\\ell\\rho_0a\\int_a^R dr^\\prime=2\\pi\\ell\\rho_0a(R-a)', []),
          S('把两项电荷相加后代入高斯定律，最后约去共同长度和 2π。', 'Add both charge terms, substitute into Gauss’s law and cancel the common length and 2π.', '2\\pi R\\ell\\epsilon E_r(R)=2\\pi a\\ell[\\rho_{sa}+\\rho_0(R-a)]', []),
          S('除以 εR，并把任意高斯半径 R 改记为观察半径 r。', 'Divide by εR and relabel the arbitrary Gaussian radius R as observation radius r.', '\\mathbf E(r)=\\frac{a}{\\epsilon r}[\\rho_{sa}+\\rho_0(r-a)]\\hat{\\mathbf r}', [])],r'\mathbf E(r)=\frac{a}{\epsilon r}[\rho_{sa}+\rho_0(r-a)]\hat{\mathbf r}',6,figure='leaky-gauss',figureCaption=L('保持同轴线三维视角，标出 a<R<b 的闭合高斯圆柱及长度 ℓ。', 'Coaxial geometry in its 3D perspective, showing a closed Gaussian cylinder with a<R<b and length ℓ.')),
        P('b',0,'求 $V(r)$。','Find $V(r)$.',[
          S('先写电势差原式，参考点选题设接地的外导体。', 'Begin with the potential-difference integral, referenced to the grounded outer conductor.', 'V(r)-V(b)=-\\int_b^r\\mathbf E\\cdot d\\mathbf l,\\qquad V(b)=0', ['potential']),
          S('选径向路径，积分变量用 s，避免和终点 r 混淆。', 'Use a radial path and integration variable s, distinct from endpoint r.', 'd\\mathbf l=\\hat{\\mathbf r}\\,ds,\\qquad V(r)=-\\int_b^r\\frac{a}{\\epsilon s}[\\rho_{sa}+\\rho_0(s-a)]\\,ds', []),
          S('将括号展开成 1/s 项和常数项，再把积分上下限反转去掉外侧负号。', 'Expand into a 1/s term and a constant, then reverse the limits to remove the leading minus sign.', 'V(r)=\\frac a\\epsilon\\int_r^b\\left[\\frac{\\rho_{sa}-a\\rho_0}{s}+\\rho_0\\right]ds', []),
          S('分别积分：第一项产生对数，第二项产生线性距离。', 'Integrate separately: the first term gives a logarithm and the second a linear distance.', 'V(r)=\\frac a\\epsilon\\left[(\\rho_{sa}-a\\rho_0)\\,[\\ln s]_r^b+\\rho_0[s]_r^b\\right]', []),
          S('代入两端，使用 ln b−ln r=ln(b/r)。在 r=b 时对数项和线性项都为零。', 'Evaluate both endpoints and use ln b−ln r=ln(b/r). Both terms vanish at r=b.', 'V(r)=\\frac a\\epsilon\\left[(\\rho_{sa}-a\\rho_0)\\ln\\frac br+\\rho_0(b-r)\\right]', [])],r'V(r)=\frac a\epsilon\left[(\rho_{sa}-a\rho_0)\ln\frac br+\rho_0(b-r)\right]',7),
        P('c',0,'求 $V_0=V(a)-V(b)$，并用 V₀、ρ₀ 表示 ρsa。','Find $V_0=V(a)-V(b)$ and express ρsa in terms of V₀ and ρ₀.',[
          S('先按定义写两导体电势差，再把上一问电位函数取在 a 和 b。', 'Begin with the conductor potential difference and evaluate the preceding potential at a and b.', 'V_0=V(a)-V(b),\\qquad V(b)=0', ['potential']),
          S('将 r=a 代入，保留完整的对数项与线性项。', 'Substitute r=a, retaining both logarithmic and linear contributions.', 'V_0=\\frac a\\epsilon\\left[(\\rho_{sa}-a\\rho_0)\\ln\\frac ba+\\rho_0(b-a)\\right]', []),
          S('两边乘 ε/a，先消去最外层的系数。', 'Multiply both sides by ε/a to remove the outer coefficient.', '\\frac{\\epsilon V_0}{a}=(\\rho_{sa}-a\\rho_0)\\ln(b/a)+\\rho_0(b-a)', []),
          S('把与 ρsa 无关的线性项移到左边，再除以 ln(b/a)。', 'Move the linear term independent of ρsa to the left and divide by ln(b/a).', '\\rho_{sa}-a\\rho_0=\\frac{\\epsilon V_0/a-\\rho_0(b-a)}{\\ln(b/a)}', []),
          S('最后加回 aρ₀，并把分子展开；每一项的量纲都是 C/m²。', 'Add back aρ₀ and expand the numerator. Every term has dimension C/m².', '\\rho_{sa}=\\frac{\\epsilon V_0}{a\\ln(b/a)}+a\\rho_0-\\frac{\\rho_0(b-a)}{\\ln(b/a)}', [])],r'\rho_{sa}=\frac{\epsilon V_0}{a\ln(b/a)}+a\rho_0-\frac{\rho_0(b-a)}{\ln(b/a)}',7),
        P('d',0,'按 $C=dQ/dV_0$ 定义求单位长度电容。','Find capacitance per unit length using $C=dQ/dV_0$.',[
          S('本题明确要求微分电容：背景空间电荷保持不变，只改变两导体间电势差。', 'Use the differential capacitance required by the question: hold the background space charge fixed while varying the conductor voltage.', 'C^\\prime=\\frac1\\ell\\left.\\frac{\\partial Q}{\\partial V_0}\\right|_{\\rho_0}=\\left.\\frac{\\partial Q^\\prime}{\\partial V_0}\\right|_{\\rho_0}', ['capacitance']),
          S('先用内导体表面电荷密度求每单位长度电荷。', 'First convert the inner-conductor surface density to charge per unit length.', 'Q=2\\pi a\\ell\\rho_{sa},\\qquad Q^\\prime=\\frac Q\\ell=2\\pi a\\rho_{sa}', []),
          S('把 c) 求出的 ρsa 完整代入。', 'Substitute the full expression for ρsa from part c).', 'Q^\\prime=2\\pi a\\left[\\frac{\\epsilon V_0}{a\\ln(b/a)}+a\\rho_0-\\frac{\\rho_0(b-a)}{\\ln(b/a)}\\right]', []),
          S('把含 V₀ 的线性项与固定电荷造成的偏移量分开。', 'Separate the term linear in V₀ from the fixed-charge offset.', 'Q^\\prime=\\frac{2\\pi\\epsilon}{\\ln(b/a)}V_0+2\\pi a\\rho_0\\left[a-\\frac{b-a}{\\ln(b/a)}\\right]', []),
          S('对 V₀ 求导。第一项留下系数，第二项在固定 ρ₀ 时导数为零。', 'Differentiate with respect to V₀. The first term leaves its coefficient and the fixed-ρ₀ offset has zero derivative.', '\\frac{\\partial Q^\\prime}{\\partial V_0}=\\frac{2\\pi\\epsilon}{\\ln(b/a)}(1)+0', []),
          S('所以空间电荷改变 Q–V 曲线截距，却不改变这里的斜率。', 'Space charge changes the Q–V intercept but not the slope in this model.', 'C^\\prime=\\frac{2\\pi\\epsilon}{\\ln(b/a)}\\quad[\\mathrm{F/m}]', [])],r'C^\prime=\frac{2\pi\epsilon}{\ln(b/a)}\quad[\mathrm{F/m}]',7)
      ],caption=('介质中的体电荷用点阵示意，虚线为同轴高斯面。右图仅示例取 b=3a、ρsa=2aρ₀ 的归一化场与电势。','Dots indicate space charge; the dashed cylinder is Gaussian. Profiles illustrate b=3a and ρsa=2aρ₀ in normalized units.'))

    images=Q(s,4,'导体平面上方的点电荷','Point charges above a conducting plane',('镜像法 · 面电荷','Method of images · surface charge'),
      (r'理想导体占据 $z<0$。电荷 $-q$ 位于 $(-x_0,0,z_0)$，$+q$ 位于 $(x_0,0,z_0)$。上方介电常数为 $\epsilon_0$，求表面点 $P=(x,0,0)$ 的电场与感应电荷。',
       r'A perfect conductor occupies $z<0$. A charge $-q$ is at $(-x_0,0,z_0)$ and $+q$ at $(x_0,0,z_0)$. Above the conductor the permittivity is $\epsilon_0$. Find the field and induced charge at $P=(x,0,0)$ on its surface.'),
      [r'\mathbf r_- =(-x_0,0,z_0)',r'\mathbf r_+=(x_0,0,z_0)',r'P=(x,0,0^+)'],10,8,[.20,.17,.62,.22],
      [R(11,43,'导体与镜像法','Conductors and image charges'),R(12,16,'导体表面的法向电场','Normal field at a conductor')],[
        P('a',0,'画出真实电荷、镜像电荷、坐标及导体界面。','Draw the real and image charges, coordinates and conducting interface.',[
          S('镜像构造要满足导体边界：表面为等势面，导体内部静电场为零。', 'The image construction must satisfy an equipotential conducting surface and zero electrostatic field inside the conductor.', 'V(x,y,0)=\\text{constant},\\qquad E_t(x,y,0^+)=0', ['boundary', 'potential']),
          S('在 x–z 平面先画 z=0，再标出两个真实电荷及其坐标；二者的 y 坐标均为零。', 'Draw z=0 in the x–z plane, then place both real charges with coordinates; both have y=0.', '-q:\\ (-x_0,0,z_0),\\qquad +q:\\ (x_0,0,z_0)', []),
          S('对左边的 −q，位置关于 z=0 反射，符号反转，得到位于下方的 +q。', 'Reflect the left −q across z=0 and reverse its sign, obtaining +q below the plane.', 'q_{\\mathrm{im},L}=+q,\\qquad \\mathbf r_{\\mathrm{im},L}=(-x_0,0,-z_0)', []),
          S('对右边的 +q 作相同操作，得到下方的 −q；上下高度均应标为 z₀。', 'Do the same for the right +q, obtaining −q below the plane. Mark equal heights z₀ above and below.', 'q_{\\mathrm{im},R}=-q,\\qquad\\mathbf r_{\\mathrm{im},R}=(x_0,0,-z_0)', []),
          S('核对边界：平面上每一对真实电荷与镜像到观察点距离相等、电荷符号相反，电位逐对抵消。', 'Check the boundary: each real charge and its image are equidistant from a point on the plane and have opposite signs, so their potentials cancel pairwise.', 'V_{\\mathrm{pair}}(z=0)=\\frac1{4\\pi\\epsilon_0}\\left(\\frac{q_i}{R_i}-\\frac{q_i}{R_i}\\right)=0', ['coulomb']),
          S('这四个点构成用于求上半空间场的数学系统，下面的镜像电荷不是导体中的真实点电荷。', 'These four points define the mathematical system for the upper-half-space field; the images are not physical point charges inside the conductor.', 'q_{\\mathrm{im},L}=+q,\\qquad q_{\\mathrm{im},R}=-q', [])],r'q_{\mathrm{im},L}=+q,\qquad q_{\mathrm{im},R}=-q',8,figure='images-geometry',answerText=L('镜像只用于求 z>0 的真实场；z<0 是数学延拓区域。','Images reproduce the physical field only for z>0; z<0 is a mathematical extension.'),figureCaption=L('x–z 平面的四电荷镜像构造，标出真实和镜像电荷坐标及导体表面 z=0。', 'Four-charge image construction in the x–z plane, with real/image coordinates and conducting surface z=0.')),
        P('b',0,'画出含镜像区域的电场线。','Sketch field lines, including the image region.',[
          S('先写四点电荷的库仑场叠加式，场线切线方向必须与该合场一致。', 'Begin with the Coulomb superposition of all four charges; field-line tangents must follow that total field.', '\\mathbf E(\\mathbf r)=\\frac1{4\\pi\\epsilon_0}\\sum_iq_i\\frac{\\mathbf r-\\mathbf r_i}{|\\mathbf r-\\mathbf r_i|^3}', ['coulomb']),
          S('逐一代入 a) 的位置和符号：右上、左下为正，左上、右下为负。', 'Substitute the positions and signs from a): upper right and lower left are positive; upper left and lower right are negative.', '(x_i,z_i,q_i)=(-x_0,z_0,-q),\\ (x_0,z_0,q),\\ (-x_0,-z_0,q),\\ (x_0,-z_0,-q)', []),
          S('在平面上，真实电荷与对应镜像的切向场抵消、法向场相加，所以场线必须垂直穿过 z=0。', 'On the plane, each real–image pair cancels tangential field and adds normal field, so field lines meet z=0 normally.', 'E_x(x,0,0)=0,\\qquad \\mathbf E(x,0,0)\\parallel\\hat{\\mathbf z}', ['boundary']),
          S('箭头从正电荷出发、到负电荷结束；图中上方主要由右向左，下方主要由左向右，符合四电荷的符号。', 'Arrows leave positive charges and end on negative charges: mainly right to left above and left to right below, consistent with all four signs.', '\\frac{d\\mathbf r}{ds}\\parallel\\mathbf E(\\mathbf r)', []),
          S('图中场线形状为对称几何示意，弯曲程度随 x₀/z₀ 改变。下半空间只表示镜像系统，真实导体内部 E=0。', 'The lines illustrate the symmetric geometry; their curvature depends on x₀/z₀. Below the plane they show the image system only; the physical conductor has E=0.', '\\mathbf E(0^+)\\parallel\\hat{\\mathbf z}', [])],r'\mathbf E(0^+)\parallel\hat{\mathbf z}',8,figure='images-fieldlines',answerText=L('图中箭头给出方向，导体内部真实电场为零。','Arrows show direction; the physical field inside the conductor is zero.'),figureCaption=L('场线以 x₀=z₀ 作几何示意，从正电荷到负电荷；下半空间仅为数学镜像系统，实际导体内部电场为零。', 'Illustrative field lines with x₀=z₀, from positive to negative charges; the lower half is only the image system, and the physical conductor field is zero.')),
        P('c',0,'忽略导体，仅求真实 +q 在 P 处产生的场。','Ignoring the conductor, find the field at P from the real +q alone.',[
          S('先写原表的点电荷电场。将单位径向矢量换成位移除以距离，就得到适合坐标代入的形式。', 'Begin with the crib point-charge field. Replace the radial unit vector by displacement divided by distance for coordinate substitution.', '\\mathbf E=\\frac q{4\\pi\\epsilon_0R^2}\\hat{\\mathbf R}=\\frac{q\\mathbf R}{4\\pi\\epsilon_0R^3}', ['coulomb']),
          S('源电荷位于 (x₀,0,z₀)，观察点为 (x,0,0)；位移必须是观察点减源点。', 'The source is at (x₀,0,z₀) and observation point at (x,0,0). Displacement is observation minus source.', '\\mathbf R_+=(x,0,0)-(x_0,0,z_0)=(x-x_0)\\hat{\\mathbf x}-z_0\\hat{\\mathbf z}', []),
          S('逐分量求距离和单位矢量，注意 z 分量为负。', 'Compute the distance and unit vector component by component, keeping the negative z component.', 'R_+=\\sqrt{(x-x_0)^2+z_0^2},\\qquad \\hat{\\mathbf R}_+=\\frac{(x-x_0)\\hat{\\mathbf x}-z_0\\hat{\\mathbf z}}{\\sqrt{(x-x_0)^2+z_0^2}}', []),
          S('将 q、位移和距离完整代入库仑定律。此问明确忽略导体，因此不加入镜像。', 'Substitute the charge, displacement and distance into Coulomb’s law. This part explicitly ignores the conductor, so include no image charges.', '\\mathbf E_{+q}(P)=\\frac{q[(x-x_0)\\hat{\\mathbf x}-z_0\\hat{\\mathbf z}]}{4\\pi\\epsilon_0[(x-x_0)^2+z_0^2]^{3/2}}', [])],r'\mathbf E_{+q}(P)=\frac{q[(x-x_0)\hat{\mathbf x}-z_0\hat{\mathbf z}]}{4\pi\epsilon_0[(x-x_0)^2+z_0^2]^{3/2}}',9),
        P('d',0,'计入两个真实电荷与导体后，求 P 处总电场。','Find the total field at P including both real charges and the conductor.',[
          S('总场由两个真实电荷和两个镜像电荷相加得到，不能只把 c) 的单个电场乘二。', 'The total field sums both real charges and both images; doubling the single field in c) is insufficient.', '\\mathbf E_{\\mathrm{tot}}=\\frac1{4\\pi\\epsilon_0}\\sum_{i=1}^4q_i\\frac{\\mathbf R_i}{R_i^3}', ['coulomb']),
          S('用 R_L、R_R 分别表示观察点到左、右电荷列的距离；每列上下电荷到平面的距离相同。', 'Use R_L and R_R for distances from P to the left and right charge columns. Within a column, real and image distances to P agree.', 'R_L=\\sqrt{(x+x_0)^2+z_0^2},\\qquad R_R=\\sqrt{(x-x_0)^2+z_0^2}', []),
          S('先展开右列：真实 +q 和镜像 −q 的 x 分量相消，z 分量相加为 −2qz₀。', 'Expand the right column first: real +q and image −q cancel in x and add to −2qz₀ in z.', '\\begin{aligned}\\mathbf E_R&=\\frac{q[(x-x_0)\\hat{\\mathbf x}-z_0\\hat{\\mathbf z}]}{4\\pi\\epsilon_0R_R^3}\\\\&\\quad-\\frac{q[(x-x_0)\\hat{\\mathbf x}+z_0\\hat{\\mathbf z}]}{4\\pi\\epsilon_0R_R^3}\\\\&=-\\frac{2qz_0}{4\\pi\\epsilon_0R_R^3}\\hat{\\mathbf z}\\end{aligned}', []),
          S('再展开左列：真实 −q 和镜像 +q 的切向分量相消，法向分量给出相反的正号。', 'Expand the left column next: real −q and image +q cancel tangentially and give the opposite, positive normal sign.', '\\begin{aligned}\\mathbf E_L&=-\\frac{q[(x+x_0)\\hat{\\mathbf x}-z_0\\hat{\\mathbf z}]}{4\\pi\\epsilon_0R_L^3}\\\\&\\quad+\\frac{q[(x+x_0)\\hat{\\mathbf x}+z_0\\hat{\\mathbf z}]}{4\\pi\\epsilon_0R_L^3}\\\\&=+\\frac{2qz_0}{4\\pi\\epsilon_0R_L^3}\\hat{\\mathbf z}\\end{aligned}', []),
          S('相加并提取公因子；这也显式验证了导体表面的切向场为零。', 'Add and factor the common coefficient, explicitly verifying zero tangential field at the conductor.', '\\mathbf E_{\\mathrm{tot}}(P)=\\frac{qz_0}{2\\pi\\epsilon_0}\\left(\\frac1{R_L^3}-\\frac1{R_R^3}\\right)\\hat{\\mathbf z}', [])],r'\mathbf E_{\mathrm{tot}}(P)=\frac{qz_0}{2\pi\epsilon_0}\left(\frac1{R_L^3}-\frac1{R_R^3}\right)\hat{\mathbf z}',9),
        P('e',0,'求导体表面在 P 处的面电荷密度。','Find the induced surface charge density at P.',[
          S('先写原表的法向位移跳变条件，法向取从导体指向空气的 +ẑ。', 'Begin with the crib normal-displacement jump condition, using +ẑ from conductor into air.', 'D_{\\mathrm{out},n}-D_{\\mathrm{in},n}=\\rho_s,\\qquad\\hat{\\mathbf n}=+\\hat{\\mathbf z}', ['boundary']),
          S('导体内部 D=0，外部为 ε₀E；因此表面电荷等于外侧电场的有符号法向分量乘 ε₀。', 'Inside the conductor D=0 and outside D=ε₀E, so surface charge is ε₀ times the signed exterior normal field.', '\\rho_s=\\epsilon_0\\mathbf E(0^+)\\cdot\\hat{\\mathbf z}=\\epsilon_0 E_z(0^+)', ['constitutive']),
          S('完整代入 d) 的电场，先保留 ε₀ 因子再约去。', 'Substitute the full field from d), retaining ε₀ before cancellation.', '\\rho_s=\\epsilon_0\\frac{qz_0}{2\\pi\\epsilon_0}\\left(\\frac1{R_L^3}-\\frac1{R_R^3}\\right)=\\frac{qz_0}{2\\pi}\\left(\\frac1{R_L^3}-\\frac1{R_R^3}\\right)', []),
          S('用位置坐标展开距离；在 x=0 两项相等，右侧 x>0 对应负的感应电荷，可作符号核对。', 'Expand the distances in coordinates. At x=0 the terms cancel; for x>0 the induced charge is negative, providing a sign check.', '\\rho_s(x)=\\frac{qz_0}{2\\pi}\\left[\\frac1{((x+x_0)^2+z_0^2)^{3/2}}-\\frac1{((x-x_0)^2+z_0^2)^{3/2}}\\right]', [])],r'\rho_s(x)=\frac{qz_0}{2\pi}\left[\frac1{((x+x_0)^2+z_0^2)^{3/2}}-\frac1{((x-x_0)^2+z_0^2)^{3/2}}\right]',10)
      ],caption=('实心点为真实电荷，虚线圆为镜像。下半区域的场线表示数学镜像系统；真实导体内部 E=0。','Filled dots are real charges and dashed circles are images. Lower field lines depict the image system; the real conductor has E=0 inside.'))
    return [E(f,2,('秋季','Fall'),2025,42,[sphere,plates,coax,dipole]),E(s,2,('春季','Spring'),2026,32,[microstrip,boundary,leaky,images])]
